<script setup>
import { computed, onMounted, reactive, ref } from 'vue';
import { RouterLink } from 'vue-router';
import { toast } from 'vue-sonner';
import DefinitionPage from '../../components/shared/DefinitionPage.vue';
import DefinitionDialog from '../../components/shared/DefinitionDialog.vue';
import { listPhysicalDevices, createPhysicalDevice, updatePhysicalDevice, matchPhysicalDevice } from '../../services/inventory';
import { getPharmacies, getKioskStatus } from '../../services/devices';
import { humanError } from '../../services/api';
const records = ref([]), pharmacies = ref([]), kiosks = ref([]), loading = ref(false), error = ref(''), search = ref(''), state = ref('');
const open = ref(false), saving = ref(false), formError = ref(''), matching = ref(null), selectedKiosk = ref('');
const empty = () => ({ id: null, seri_no: '', marka: '', model: '', ekran_boyutu: '', garanti_ay: '', donanim_degeri: '', eczane: '', aktif: true, notlar: '' });
const form = reactive(empty());
const filtered = computed(() => records.value.filter(row => (!state.value || (state.value === 'matched' ? !!row.kiosk : !row.kiosk)) && `${row.seri_no} ${row.marka} ${row.model} ${row.eczane_ad}`.toLocaleLowerCase('tr').includes(search.value.toLocaleLowerCase('tr'))));
const matchOptions = computed(() => kiosks.value.filter(row => !matching.value?.eczane || row.pharmacyId === matching.value.eczane));
async function load() { loading.value = true; error.value = ''; try { const { data } = await listPhysicalDevices(); records.value = Array.isArray(data) ? data : data.results || []; } catch (e) { error.value = humanError(e); } finally { loading.value = false; } }
function edit(row = null) { Object.assign(form, empty(), row || {}, { eczane: row?.eczane || '', garanti_ay: row?.garanti_ay ?? '', donanim_degeri: row?.donanim_degeri ?? '' }); formError.value = ''; open.value = true; }
async function save() { saving.value = true; formError.value = ''; const { seri_no, marka, model, ekran_boyutu, garanti_ay, donanim_degeri, eczane, aktif, notlar } = form; const payload = { seri_no, marka, model, ekran_boyutu, garanti_ay: garanti_ay === '' ? null : garanti_ay, donanim_degeri: donanim_degeri === '' ? null : donanim_degeri, eczane: eczane || null, aktif, notlar }; try { form.id ? await updatePhysicalDevice(form.id, payload) : await createPhysicalDevice(payload); open.value = false; toast.success('Cihaz kaydedildi.'); await load(); } catch (e) { formError.value = humanError(e); } finally { saving.value = false; } }
async function openMatch(row) { matching.value = row; selectedKiosk.value = ''; formError.value = ''; try { kiosks.value = await getKioskStatus(); } catch (e) { formError.value = humanError(e); } }
async function match() { if (!selectedKiosk.value) { formError.value = 'Eşleştirilecek kiosku seçin.'; return; } saving.value = true; try { await matchPhysicalDevice(matching.value.id, selectedKiosk.value); matching.value = null; toast.success('Seri numarası kiosk ile eşleştirildi.'); await load(); } catch (e) { formError.value = humanError(e); } finally { saving.value = false; } }
onMounted(async () => { await load(); try { pharmacies.value = await getPharmacies(); } catch (e) { error.value = humanError(e); } });
</script>
<template>
  <DefinitionPage v-model:search="search" title="Cihaz Tanımları" eyebrow="ECZANE & KİOSK / DONANIM" description="Fiziksel cihazları seri numarasıyla kaydedin ve provizyondaki kiosk ile eşleştirin." :count="filtered.length" :loading="loading" :error="error" new-label="Yeni Cihaz" @create="edit()" @refresh="load">
    <template #filters><select v-model="state" class="eisa-field eisa-filter" aria-label="Eşleştirme durumu"><option value="">Tüm cihazlar</option><option value="unmatched">Eşleşme bekleyen</option><option value="matched">Kiosk ile eşleşen</option></select><RouterLink to="/admin/devices/pending" class="eisa-btn eisa-btn-ghost"><i class="fa-solid fa-link"></i>Provizyon Talepleri</RouterLink></template>
    <div v-if="filtered.length" class="eisa-table-wrap"><table class="eisa-table"><thead><tr><th>Seri numarası</th><th>Cihaz</th><th>Eczane</th><th>Kiosk eşleşmesi</th><th>İşlemler</th></tr></thead><tbody><tr v-for="row in filtered" :key="row.id"><td><span class="eisa-record-name">{{ row.seri_no }}</span><span v-if="!row.aktif" class="eisa-pill eisa-pill-muted">Pasif</span></td><td>{{ row.marka }} {{ row.model }}<span class="eisa-record-detail">{{ row.ekran_boyutu || 'Ekran bilgisi girilmedi' }}</span></td><td>{{ row.eczane_ad || 'Stokta / atanmamış' }}</td><td><span class="eisa-pill" :class="row.kiosk ? 'eisa-pill-success' : 'eisa-pill-warning'">{{ row.kiosk ? row.kiosk_ad : 'Provizyon bekliyor' }}</span><span v-if="row.kiosk_mac" class="eisa-record-detail">{{ row.kiosk_mac }}</span></td><td><div class="eisa-table-actions"><button v-if="!row.kiosk" class="eisa-icon-btn" aria-label="Kiosk ile eşleştir" title="Kiosk ile eşleştir" @click="openMatch(row)"><i class="fa-solid fa-link"></i></button><button class="eisa-icon-btn" aria-label="Cihazı düzenle" title="Cihazı düzenle" @click="edit(row)"><i class="fa-solid fa-pen"></i></button></div></td></tr></tbody></table></div>
    <div v-else class="eisa-definition-empty"><i class="fa-solid fa-display"></i><strong>Fiziksel cihaz kaydı bulunamadı</strong><span>Seri numarasını kiosk açılmadan önce kaydedebilirsiniz.</span></div>
    <template #dialogs>
      <DefinitionDialog :open="open" :title="form.id ? 'Cihazı Düzenle' : 'Yeni Fiziksel Cihaz'" :busy="saving" :error="formError" @close="open = false" @save="save"><div class="eisa-form-grid">
        <label class="eisa-form-row eisa-form-row-full"><span class="eisa-field-label">Üretici seri numarası *</span><input v-model.trim="form.seri_no" class="eisa-field" required maxlength="128" placeholder="Cihaz üzerindeki gerçek seri numarası" /></label>
        <label class="eisa-form-row"><span class="eisa-field-label">Marka</span><input v-model.trim="form.marka" class="eisa-field" maxlength="100" /></label><label class="eisa-form-row"><span class="eisa-field-label">Model *</span><input v-model.trim="form.model" class="eisa-field" required maxlength="150" /></label>
        <label class="eisa-form-row"><span class="eisa-field-label">Ekran / donanım bilgisi</span><input v-model.trim="form.ekran_boyutu" class="eisa-field" placeholder="Örn. 21,5 inç FHD" /></label><label class="eisa-form-row"><span class="eisa-field-label">Garanti süresi (ay)</span><input v-model.number="form.garanti_ay" class="eisa-field" type="number" min="0" placeholder="Belirlenmediyse boş bırakın" /></label>
        <label class="eisa-form-row"><span class="eisa-field-label">Donanım değeri (TL)</span><input v-model="form.donanim_degeri" class="eisa-field" type="number" step="0.01" min="0" /></label><label class="eisa-form-row"><span class="eisa-field-label">Ayrıldığı eczane</span><select v-model="form.eczane" class="eisa-field"><option value="">Stokta / henüz atanmamış</option><option v-for="pharmacy in pharmacies" :key="pharmacy.id" :value="pharmacy.id">{{ pharmacy.name }}</option></select></label>
        <label class="eisa-form-row eisa-form-row-full"><span class="eisa-field-label">Notlar</span><textarea v-model="form.notlar" class="eisa-field" rows="2"></textarea></label>
      </div><div class="eisa-form-section"><label class="eisa-toggle"><input v-model="form.aktif" type="checkbox" />Cihaz aktif</label><span class="eisa-form-note">MAC adresi veya cihaz UUID’si üretici seri numarası yerine kullanılmaz.</span></div></DefinitionDialog>
      <DefinitionDialog :open="!!matching" title="Kiosk ile Eşleştir" :busy="saving" :error="formError" save-label="Eşleştir" @close="matching = null" @save="match"><p class="eisa-reset-info">Seri numarası: <strong>{{ matching?.seri_no }}</strong></p><label class="eisa-form-row"><span class="eisa-field-label">Kiosk</span><select v-model="selectedKiosk" class="eisa-field" required><option value="">Kiosk seçin</option><option v-for="kiosk in matchOptions" :key="kiosk.id" :value="kiosk.id">{{ kiosk.pharmacyName }} / {{ kiosk.ad }} / {{ kiosk.mac }}</option></select></label></DefinitionDialog>
    </template>
  </DefinitionPage>
</template>
